create table public.hands_commands (id uuid primary key default gen_random_uuid(), task_id text not null unique, status text not null default 'queued' check (status in ('queued','claimed','completed','error')), command jsonb not null, worker_id text, created_at timestamptz not null default now(), claimed_at timestamptz, completed_at timestamptz, error text); create table public.hands_results (id bigint generated by default as identity primary key, task_id text not null, result jsonb not null, worker_id text, created_at timestamptz not null default now()); create index hands_commands_status_created_idx on public.hands_commands(status, created_at); create index hands_results_task_id_idx on public.hands_results(task_id);;
